#include <algorithm>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>
#include <glm/glm.hpp>
import Geometry;
import Geometry.HalfedgeMesh.CurvatureSegmentation.Features;
import Geometry.HalfedgeMesh.CurvatureSegmentation.Patches;
namespace CS = Geometry::CurvatureSegmentation;
int main(int argc,char**argv) {
 if(argc!=3)return 2;
 auto source=Geometry::MeshIO::LoadOBJ(argv[1]); if(!source)return 3;
 auto positions=source->Vertices.Get<glm::vec3>("v:point");
 auto faces=source->Faces.Get<std::vector<std::uint32_t>>("f:vertices");
 Geometry::HalfedgeMesh::Mesh mesh; std::vector<Geometry::VertexHandle> verts;
 for(auto p:positions.Span())verts.push_back(mesh.AddVertex(p));
 for(auto& f:faces.Vector()) {if(f.size()!=3)return 4; if(!mesh.AddTriangle(verts[f[0]],verts[f[1]],verts[f[2]]))return 5;}
 auto curv=Geometry::Curvature::ComputeCurvature(mesh);
 auto evidence=CS::DetectFeatureEvidence(mesh,curv.MaxPrincipalCurvatureProperty.Vector(),curv.MinPrincipalCurvatureProperty.Vector());
 auto& e=evidence.Diagnostics;
 std::cout<<"{\"stage\":\"features\",\"mesh\":\""<<argv[1]<<"\",\"vertices\":"<<mesh.VertexCount()<<",\"faces\":"<<mesh.FaceCount()<<",\"status\":\""<<CS::ToString(e.Status)<<"\",\"hard\":"<<e.HardFeatureEdgeCount<<",\"soft\":"<<e.RetainedSoftEdgeCount<<",\"strong\":"<<e.StrongEdgeCount<<",\"weak_disconnected\":"<<e.WeakDisconnectedEdgeCount<<",\"short_rejected\":"<<e.ShortFragmentRejectedEdgeCount<<",\"endpoints\":"<<e.EndpointVertexCount<<",\"junctions\":"<<e.JunctionVertexCount<<",\"source_boundary\":"<<e.SourceBoundaryEdgeCount<<"}"<<std::endl;
 if(!evidence.Succeeded())return 6;
 for(bool fixed : {false,true}) for(double beta:{0.5,0.05,0.0025}) {
 CS::CurvaturePatchParams p; p.Mixture.SelectionMode=fixed?CS::ComponentSelectionMode::FixedCount:CS::ComponentSelectionMode::Automatic;p.Mixture.FixedComponentCount=6;p.PatchComplexityCost=beta;
 auto r=CS::SegmentFeatureAlignedPatches(mesh,curv.MaxPrincipalCurvatureProperty.Vector(),curv.MinPrincipalCurvatureProperty.Vector(),evidence.View(),p);
 auto& d=r.Diagnostics;
 std::cout<<"{\"stage\":\"patches\",\"fixed6\":"<<fixed<<",\"beta\":"<<beta<<",\"status\":\""<<CS::ToString(d.Status)<<"\",\"components\":"<<d.SelectedComponentCount<<",\"seeds\":"<<d.SeedCount<<",\"provisional\":"<<d.ProvisionalRegionCount<<",\"merges\":"<<d.AcceptedMergeCount<<",\"regions\":"<<d.FinalRegionCount<<",\"boundaries\":"<<d.FinalBoundaryEdgeCount<<",\"hard\":"<<d.HardBoundaryEdgeCount<<",\"soft\":"<<d.SoftBoundaryEdgeCount<<",\"closure\":"<<d.ClosureBoundaryEdgeCount<<",\"energy\":"<<d.FinalEnergy<<",\"region_sizes\":[";
 bool first=true;for(auto&region:r.Regions){if(!first)std::cout<<',';first=false;std::cout<<region.FaceCount;}std::cout<<"]}"<<std::endl;
 if(!r.Succeeded())return 7;
 std::string stem=std::string(argv[2])+"/"+(fixed?"fixed6":"auto")+"-"+std::to_string(beta);
 std::ofstream labels(stem+".labels");for(auto f:mesh.LiveFaces())labels<<r.FaceRegions[f.Index]<<'\n';
 std::ofstream edges(stem+".edges");for(auto edge:mesh.LiveEdges()){auto h=mesh.Halfedge(edge,0);edges<<mesh.FromVertex(h).Index<<' '<<mesh.ToVertex(h).Index<<' '<<int(evidence.HardEdgeMask[edge.Index])<<' '<<evidence.SoftEdgeConfidence[edge.Index]<<' '<<int(r.EdgeBoundaryRoles[edge.Index])<<'\n';}
 }
}

